style.css:
@-moz-document domain("docs.google.com") {
/* Fondo oscuro */
    body, .docs-title, .docs-menubar, .docs-toolbar, .docs-sidebar {
        background-color: #1a1a1a !important;
        color: #e0e0e0 !important;
    }

    /* Texto principal */
    .kix-page-content, .kix-paragraphrenderer, .kix-lineview-text {
        color: #e0e0e0 !important;
    }

    /* Barra de herramientas */
    .docs-toolbar {
        background-color: #2d2d2d !important;
        border-bottom: 1px solid #444 !important;
    }

    /* Botones y controles */
    .goog-toolbar-button, .docs-toolbar-button, .docs-titlebar-buttons {
        background-color: #333 !important;
        color: #e0e0e0 !important;
        border: 1px solid #444 !important;
    }

    /* Barra lateral */
    .docs-sidebar {
        background-color: #222 !important;
        border-right: 1px solid #444 !important;
    }

    /* Enlaces */
    a {
        color: #8a2be2 !important; /* Morado gótico */
    }

    /* Encabezados */
    h1, h2, h3, h4, h5, h6 {
        color: #8a2be2 !important; /* Morado gótico */
    }

    /* Cursor y selección */
    ::selection {
        background-color: #8a2be2 !important; /* Morado gótico */
        color: #fff !important;
    }

    /* Scrollbar */
    ::-webkit-scrollbar {
        width: 10px;
    }

    ::-webkit-scrollbar-track {
        background: #2d2d2d;
    }

    ::-webkit-scrollbar-thumb {
        background: #8a2be2; /* Morado gótico */
        border-radius: 5px;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: #7b1fa2; /* Morado más oscuro */
    }
}
